   674	// removed; the platform implementation opens it without blocking and only as
   675	// a directory, so a link, a FIFO or any other entry stays for the runtime
   676	// inventory to judge.
   677	func removeReviewGoBuildLeftovers(root *os.Root) error {
   678		// The top level is read in bounded batches and each go-build directory
   679		// is removed as it is read, so nothing accumulates; only the other
   680		// entries, which the runtime inventory will judge, count against its
   681		// bound (review rounds 5 and 6, N6 and N10).
   682		dir, err := root.Open(".")
   683		if err != nil {
   684			return fmt.Errorf("runtime cleanup inventory incomplete; resources retained")
   685		}
   686		defer dir.Close()
   687		others := 0
   688		for {
   689			batch, err := dir.Readdirnames(256)
   690			for _, name := range batch {
   691				if !reviewGoBuildDir.MatchString(name) {
   692					others++
   693					if others > reviewRuntimeMaxEntries {
   694						return fmt.Errorf("runtime cleanup inventory incomplete; resources retained")
   695					}
   696					continue
   697				}
   698				if err := removeReviewGoBuildDir(root, name); err != nil {
   699					return err
   700				}
   701			}
   702			if len(batch) == 0 {
   703				if err == nil || errors.Is(err, io.EOF) {
   704					return nil
   705				}
   706				return fmt.Errorf("runtime cleanup inventory incomplete; resources retained")
   707			}
   708		}
   709	}
